{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aircoin.example/schemas/v1/c1-vision-event.schema.json",
  "title": "C1 · Vision event (A -> B)",
  "description": "Published by vision-twin on MQTT topic miner/{miner_id}/vision about once per second (QoS 0). One message describes every registered tag the pipeline knows about in the latest analysed frame.",
  "type": "object",
  "required": ["v", "miner_id", "ts", "frame_hash", "plants"],
  "properties": {
    "v": { "$ref": "common.schema.json#/$defs/schema_version" },
    "miner_id": { "$ref": "common.schema.json#/$defs/miner_id" },
    "ts": {
      "description": "Capture time of the analysed frame.",
      "$ref": "common.schema.json#/$defs/timestamp_ms"
    },
    "frame_hash": {
      "description": "sha256 of the raw frame bytes, 0x-prefixed. Goes into the evidence hash; identical hashes over time mean a frozen camera.",
      "$ref": "common.schema.json#/$defs/bytes32_hex"
    },
    "frame_size": {
      "description": "Frame dimensions in pixels, so bbox values can be interpreted.",
      "type": "object",
      "required": ["w", "h"],
      "properties": {
        "w": { "type": "integer", "minimum": 1 },
        "h": { "type": "integer", "minimum": 1 }
      },
      "additionalProperties": false
    },
    "plants": {
      "description": "One entry per registered sticker of this miner (normally 20), including ones not currently seen (status missing/removed).",
      "type": "array",
      "maxItems": 20,
      "items": { "$ref": "#/$defs/plant" }
    },
    "unknown_tag_ids": {
      "description": "Marker IDs seen in the frame that are not in this miner's registered sticker set.",
      "type": "array",
      "items": { "$ref": "common.schema.json#/$defs/tag_id" },
      "uniqueItems": true
    },
    "source": {
      "description": "What produced the event: the Pi camera, the laptop fallback, a recorded clip, or the mock emitter.",
      "type": "string",
      "enum": ["pi_camera", "laptop_camera", "recorded", "mock"]
    }
  },
  "additionalProperties": false,
  "$defs": {
    "plant": {
      "type": "object",
      "required": ["tag_id", "species", "species_conf", "leaf_area_cm2", "alive_score", "bbox", "status"],
      "properties": {
        "tag_id": { "$ref": "common.schema.json#/$defs/tag_id" },
        "species": {
          "description": "Species enrolled for this tag (or 'unknown' if not enrolled).",
          "$ref": "common.schema.json#/$defs/species_id_or_unknown"
        },
        "species_conf": {
          "description": "Plant-match score 0-1: similarity between the live crop and the enrolled feature vector. Low = plant swapped.",
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "leaf_area_cm2": {
          "description": "Visible leaf area, smoothed, converted to cm2 using the known marker size. 0 when not seen.",
          "type": "number",
          "minimum": 0
        },
        "alive_score": {
          "description": "Liveness 0-1 (NDVI primary, match/texture fallback). Low = plastic or dead plant.",
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "ndvi": {
          "description": "Optional raw mean NDVI of the plant crop (-1 to 1), for the twin's NDVI view.",
          "type": "number",
          "minimum": -1,
          "maximum": 1
        },
        "bbox": {
          "description": "Plant bounding box [x, y, w, h] in pixels of the analysed frame; null when the tag is not seen.",
          "oneOf": [
            {
              "type": "array",
              "items": { "type": "integer", "minimum": 0 },
              "minItems": 4,
              "maxItems": 4
            },
            { "type": "null" }
          ]
        },
        "status": { "$ref": "common.schema.json#/$defs/plant_status" },
        "last_seen_ts": {
          "description": "Last time this tag was detected.",
          "$ref": "common.schema.json#/$defs/timestamp_ms"
        }
      },
      "additionalProperties": false
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aircoin.example/schemas/v1/c2-telemetry.schema.json",
  "title": "C2 · Live telemetry (B -> A, C)",
  "description": "Published by miner-core on MQTT topic miner/{miner_id}/telemetry once per second (QoS 0). Everything the twin and the admin portal need to draw the live state of one miner.",
  "type": "object",
  "required": ["v", "miner_id", "ts", "sensors", "gps", "plants", "current_epoch", "flags"],
  "properties": {
    "v": { "$ref": "common.schema.json#/$defs/schema_version" },
    "miner_id": { "$ref": "common.schema.json#/$defs/miner_id" },
    "ts": { "$ref": "common.schema.json#/$defs/timestamp_ms" },
    "scenario": {
      "description": "Active sensor-simulator scenario (free text so B can add scenarios without a contract change).",
      "type": "string",
      "examples": ["clean_morning", "rush_hour", "festival_smog", "rain_washout"]
    },
    "sensors_simulated": {
      "description": "True when air sensor values come from the simulator.",
      "type": "boolean"
    },
    "aqi": {
      "description": "Current AQI (0-500) derived from the sensors.",
      "type": "number",
      "minimum": 0,
      "maximum": 500
    },
    "sensors": { "$ref": "common.schema.json#/$defs/sensor_readings" },
    "gps": { "$ref": "common.schema.json#/$defs/gps" },
    "plants": {
      "description": "Latest known state of each plant (from C1) plus its current estimated removal rate.",
      "type": "array",
      "maxItems": 20,
      "items": {
        "type": "object",
        "required": ["tag_id", "species", "status", "leaf_area_cm2", "alive_score", "rate_air_per_h"],
        "properties": {
          "tag_id": { "$ref": "common.schema.json#/$defs/tag_id" },
          "species": { "$ref": "common.schema.json#/$defs/species_id_or_unknown" },
          "status": { "$ref": "common.schema.json#/$defs/plant_status" },
          "leaf_area_cm2": { "type": "number", "minimum": 0 },
          "alive_score": { "type": "number", "minimum": 0, "maximum": 1 },
          "species_conf": { "type": "number", "minimum": 0, "maximum": 1 },
          "rate_air_per_h": {
            "description": "Current estimated earning rate for this plant in AIR per hour (display only). 0 for missing/removed/suspect plants.",
            "type": "number",
            "minimum": 0
          }
        },
        "additionalProperties": false
      }
    },
    "current_epoch": {
      "description": "Progress of the epoch in flight.",
      "type": "object",
      "required": ["epoch", "start_ms", "end_ms", "running_air"],
      "properties": {
        "epoch": { "$ref": "common.schema.json#/$defs/epoch" },
        "start_ms": { "$ref": "common.schema.json#/$defs/timestamp_ms" },
        "end_ms": { "$ref": "common.schema.json#/$defs/timestamp_ms" },
        "running_air": {
          "description": "AIR estimated so far in this epoch (display only; the epoch message is authoritative).",
          "type": "number",
          "minimum": 0
        }
      },
      "additionalProperties": false
    },
    "flags": {
      "description": "Anti-cheat flags currently active.",
      "type": "array",
      "items": { "$ref": "common.schema.json#/$defs/anticheat_flag" }
    },
    "uplink": {
      "description": "Health of the miner -> validator link.",
      "type": "object",
      "properties": {
        "online": { "type": "boolean" },
        "queued_attestations": { "type": "integer", "minimum": 0 }
      },
      "additionalProperties": false
    },
    "device": {
      "description": "Optional Pi health for the 3D model's exploded view.",
      "type": "object",
      "properties": {
        "cpu_temp_c": { "type": "number" },
        "cpu_pct": { "type": "number", "minimum": 0, "maximum": 100 },
        "mem_pct": { "type": "number", "minimum": 0, "maximum": 100 },
        "uptime_s": { "type": "integer", "minimum": 0 }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aircoin.example/schemas/v1/c2-epoch.schema.json",
  "title": "C2 · Epoch summary (B -> A, C)",
  "description": "Published by miner-core on MQTT topic miner/{miner_id}/epoch (QoS 1, retained) when an epoch closes, and re-published for the same epoch whenever its attestation status changes (pending -> submitted -> accepted/rejected).",
  "type": "object",
  "required": ["v", "miner_id", "epoch", "start_ms", "end_ms", "plants", "by_pollutant_mg", "total_air", "attestation", "flags"],
  "properties": {
    "v": { "$ref": "common.schema.json#/$defs/schema_version" },
    "miner_id": { "$ref": "common.schema.json#/$defs/miner_id" },
    "epoch": { "$ref": "common.schema.json#/$defs/epoch" },
    "start_ms": { "$ref": "common.schema.json#/$defs/timestamp_ms" },
    "end_ms": { "$ref": "common.schema.json#/$defs/timestamp_ms" },
    "scenario": { "type": "string" },
    "sensor_summary": { "$ref": "common.schema.json#/$defs/sensor_summary" },
    "plants": {
      "description": "Per-plant estimate for the epoch (PRD 2.5 model R_i,p).",
      "type": "array",
      "maxItems": 20,
      "items": {
        "type": "object",
        "required": ["tag_id", "species", "status", "removed_mg", "air"],
        "properties": {
          "tag_id": { "$ref": "common.schema.json#/$defs/tag_id" },
          "species": { "$ref": "common.schema.json#/$defs/species_id_or_unknown" },
          "status": { "$ref": "common.schema.json#/$defs/plant_status" },
          "leaf_area_cm2": { "type": "number", "minimum": 0 },
          "health": { "type": "number", "minimum": 0, "maximum": 1 },
          "removed_mg": { "$ref": "common.schema.json#/$defs/per_pollutant_mg" },
          "air": {
            "description": "Weighted AIR for this plant this epoch (sum_p w_p * R_i,p).",
            "type": "number",
            "minimum": 0
          }
        },
        "additionalProperties": false
      }
    },
    "by_pollutant_mg": {
      "description": "Total removed per pollutant across all plants (drives the per-pollutant breakdown on stage).",
      "$ref": "common.schema.json#/$defs/per_pollutant_mg"
    },
    "total_air": {
      "description": "Epoch total in AIR (decimal, display). The attestation's amount is the authoritative base-unit value.",
      "type": "number",
      "minimum": 0
    },
    "attestation": {
      "type": "object",
      "required": ["status"],
      "properties": {
        "status": { "$ref": "common.schema.json#/$defs/attestation_status" },
        "evidence_hash": { "$ref": "common.schema.json#/$defs/bytes32_hex" },
        "amount": { "$ref": "common.schema.json#/$defs/token_amount" },
        "tx_hash": { "$ref": "common.schema.json#/$defs/tx_hash" },
        "reason_code": { "$ref": "common.schema.json#/$defs/rejection_reason_code" },
        "reason": { "type": "string" }
      },
      "additionalProperties": false
    },
    "flags": {
      "description": "Anti-cheat flags raised during this epoch.",
      "type": "array",
      "items": { "$ref": "common.schema.json#/$defs/anticheat_flag" }
    }
  },
  "additionalProperties": false
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aircoin.example/schemas/v1/c3-attestation.schema.json",
  "title": "C3 · Signed attestation (B -> C)",
  "description": "Request body of HTTPS POST /v1/attestations, sent by miner-core once per closed epoch (retried from an offline queue). See contracts-schema/README.md for how evidence_hash and signature are computed.",
  "type": "object",
  "required": ["v", "miner_id", "epoch", "start", "end", "gps", "sensor_summary", "plants", "amount", "calibration_hash", "evidence_hash", "signature"],
  "properties": {
    "v": { "$ref": "common.schema.json#/$defs/schema_version" },
    "miner_id": { "$ref": "common.schema.json#/$defs/miner_id" },
    "epoch": { "$ref": "common.schema.json#/$defs/epoch" },
    "start": {
      "description": "Epoch start, Unix ms. Must equal epoch * epoch_length_ms.",
      "$ref": "common.schema.json#/$defs/timestamp_ms"
    },
    "end": {
      "description": "Epoch end, Unix ms (exclusive).",
      "$ref": "common.schema.json#/$defs/timestamp_ms"
    },
    "gps": { "$ref": "common.schema.json#/$defs/gps" },
    "sensor_summary": { "$ref": "common.schema.json#/$defs/sensor_summary" },
    "plants": {
      "description": "Plant states for the epoch. Every tag_id must belong to this miner's registered sticker set.",
      "type": "array",
      "maxItems": 20,
      "items": {
        "type": "object",
        "required": ["tag_id", "species", "status", "leaf_area_cm2", "health", "removed_mg", "air"],
        "properties": {
          "tag_id": { "$ref": "common.schema.json#/$defs/tag_id" },
          "species": { "$ref": "common.schema.json#/$defs/species_id_or_unknown" },
          "status": { "$ref": "common.schema.json#/$defs/plant_status" },
          "leaf_area_cm2": { "type": "number", "minimum": 0 },
          "health": { "type": "number", "minimum": 0, "maximum": 1 },
          "removed_mg": { "$ref": "common.schema.json#/$defs/per_pollutant_mg" },
          "air": { "type": "number", "minimum": 0 }
        },
        "additionalProperties": false
      }
    },
    "frame_hashes": {
      "description": "sha256 of the frames used this epoch (from C1). Included so the validator can recompute evidence_hash.",
      "type": "array",
      "items": { "$ref": "common.schema.json#/$defs/bytes32_hex" }
    },
    "flags": {
      "description": "Device-side anti-cheat flags raised this epoch (informational for the validator and admin portal).",
      "type": "array",
      "items": { "$ref": "common.schema.json#/$defs/anticheat_flag" }
    },
    "amount": {
      "description": "Claimed AIR for the epoch in base units (18 decimals). This exact value is signed and minted.",
      "$ref": "common.schema.json#/$defs/token_amount"
    },
    "calibration_hash": {
      "description": "keccak256 of the canonical species-catalogue JSON used for the estimate (PRD 8.1 #5).",
      "$ref": "common.schema.json#/$defs/bytes32_hex"
    },
    "evidence_hash": { "$ref": "common.schema.json#/$defs/bytes32_hex" },
    "signature": {
      "description": "Device-key secp256k1 signature over the mint digest (README: Signing).",
      "$ref": "common.schema.json#/$defs/signature_hex"
    }
  },
  "additionalProperties": false
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aircoin.example/schemas/v1/c3-attestation-response.schema.json",
  "title": "C3 · Attestation response (C -> B)",
  "description": "Response body of POST /v1/attestations. HTTP 200 for accepted/pending, 422 for rejected, 409 when the epoch was already minted (status rejected, reason_code epoch_already_minted). The miner treats any 4xx as final and any 5xx/network error as 'retry later'.",
  "type": "object",
  "required": ["v", "miner_id", "epoch", "status"],
  "properties": {
    "v": { "$ref": "common.schema.json#/$defs/schema_version" },
    "miner_id": { "$ref": "common.schema.json#/$defs/miner_id" },
    "epoch": { "$ref": "common.schema.json#/$defs/epoch" },
    "status": {
      "description": "accepted = mint transaction confirmed; pending = verified and mint transaction sent but not yet confirmed; rejected = will never mint.",
      "type": "string",
      "enum": ["accepted", "pending", "rejected"]
    },
    "tx_hash": { "$ref": "common.schema.json#/$defs/tx_hash" },
    "amount": {
      "description": "Amount minted (base units). Equals the claimed amount when accepted.",
      "$ref": "common.schema.json#/$defs/token_amount"
    },
    "reason_code": { "$ref": "common.schema.json#/$defs/rejection_reason_code" },
    "reason": {
      "description": "Human-readable reason, shown on the admin portal and in the twin's anti-cheat log.",
      "type": "string"
    }
  },
  "allOf": [
    {
      "if": { "properties": { "status": { "const": "rejected" } } },
      "then": { "required": ["reason_code", "reason"] }
    },
    {
      "if": { "properties": { "status": { "enum": ["accepted", "pending"] } } },
      "then": { "required": ["tx_hash"] }
    }
  ],
  "additionalProperties": false
}
